head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70003";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70003.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_openDocumentPop_onclick
 * @description 「공시검토함으로 이동」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openDocumentPop_onclick = async function(e){
    try {
        await scwin.openDocumentPop('cd')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70003.btn_openDocumentPop_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openDocumentPop
 * @description open Document Pop 처리
 * @param {*} gb gb
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDocumentPop = async function (gb) {
    dAction = "";
    if (gb === "wd") {
        dAction = "/discls/searchDisclosureDocument.do?method=searchWritingDocument";
    } else {
        dAction = "/discls/searchDisclosureDocument.do?method=searchCompleteDocument";
    }
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('disclsVal', dAction) : console.warn('[sdd] hiddenStore 부재: disclsVal'));
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(dAction));
    const pageURL = '/jldods70207/jldods70207.xml';
    await $c.win.openPopup(pageURL, { id: "disclsPage", width: "770", height: "480", scrollbars: true, resizable: false, type: "pageFramePopup" }, { method: "disclsConfirmInputPop" });
};
